#include "bsp/native_renderer_shader_binding.hpp"
#include "bsp/random_threads.hpp"
#include "native_renderer_shader_binding_reference.hpp"
#include <Windows.h>
#include <excpt.h>
#include <array>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <stdexcept>
#include <vector>

namespace {
using Word=std::uint32_t;
using Entry=void (__fastcall*)(void*,Word,void*);
using Source=void (*)(void*,void*,bsp::NativeRendererSynchronizationGlobals&);
bsp::NativeRendererSynchronizationGlobals globals;
void require(bool ok,const char* message) { if(!ok) throw std::runtime_error(message); }
Word address(const void* p) { return reinterpret_cast<Word>(p); }
void* pointer(Word bits) { return reinterpret_cast<void*>(bits); }
Word load(const void* p,Word offset=0) { Word result; std::memcpy(&result,static_cast<const unsigned char*>(p)+offset,4); return result; }
void store(void* p,Word offset,Word value) { std::memcpy(static_cast<unsigned char*>(p)+offset,&value,4); }
std::uint8_t __fastcall enter_original(void* renderer) { return bsp::enter_native_renderer_optional_guard_00b33ad0(renderer,globals); }
void __fastcall leave_original(void* renderer,Word,Word ignored) { bsp::leave_native_renderer_optional_guard_00b33b00(renderer,ignored,globals); }
[[noreturn]] EXCEPTION_DISPOSITION __cdecl unexpected_original_seh(EXCEPTION_RECORD*,void*,CONTEXT*,void*) {
    TerminateProcess(GetCurrentProcess(),42); __assume(0);
}
class Original {
    void* code_; std::size_t size_;
public:
    template<std::size_t N> explicit Original(const unsigned char (&data)[N]):
        code_(VirtualAlloc(nullptr,N,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE)),size_(N) {
        require(code_!=nullptr,"VirtualAlloc"); std::memcpy(code_,data,N);
    }
    ~Original() { VirtualFree(code_,0,MEM_RELEASE); }
    template<class F> void call(std::size_t offset,F function) {
        auto* p=static_cast<unsigned char*>(code_); require(p[offset]==0xe8,"CALL relocation");
        const Word displacement=static_cast<Word>(reinterpret_cast<std::uintptr_t>(function)-reinterpret_cast<std::uintptr_t>(p+offset+5));
        std::memcpy(p+offset+1,&displacement,4);
    }
    void absolute(Word offset,Word expected,Word replacement) {
        require(load(code_,offset)==expected,"absolute relocation"); store(code_,offset,replacement);
    }
    void finish(Word original_handler) {
        call(0x2b,&enter_original); call(0xca,&leave_original);
        absolute(9,original_handler,reinterpret_cast<Word>(&unexpected_original_seh));
        for(Word offset:{0x1au,0x83u,0xb4u}) absolute(offset,0x0108d6dc,reinterpret_cast<Word>(&globals.mode_00));
        DWORD old; require(VirtualProtect(code_,size_,PAGE_EXECUTE_READ,&old)!=0,"VirtualProtect");
        require(FlushInstructionCache(GetCurrentProcess(),code_,size_)!=0,"FlushInstructionCache");
    }
    Entry entry() const { return reinterpret_cast<Entry>(code_); }
};
struct Fixture;
struct Device { Word* table; Fixture* fixture; Word id; };
struct Event { Word device,shader,cache,counter,mode,nesting,depth; bool operator==(const Event&) const=default; };
struct Snapshot { Word cache,device,counter,mode,observed,nesting,depth; std::vector<Event> events; bool operator==(const Snapshot&) const=default; };
struct Fixture {
    alignas(4) std::array<unsigned char,0x1bd0> renderer;
    bsp::TrackedCriticalSection lock{};
    std::array<std::array<Word,3>,5> logical{};
    std::array<Word,2> shader_tokens{0x33333333,0x44444444};
    std::array<Word,108> table{};
    Device first{table.data(),this,1},second{table.data(),this,2};
    Word cache_offset,counter_offset;
    unsigned calls=0;
    bool throwing=false;
    std::vector<Event> events;
    explicit Fixture(bool vertex):cache_offset(vertex?0x1770u:0x176cu),counter_offset(vertex?0x1bc0u:0x1bbcu) {
        renderer.fill(0xa5); InitializeCriticalSection(&lock.native); lock.depth=0;
        store(raw(),4,address(&lock)); store(raw(),cache_offset,0); store(raw(),counter_offset,0); store(raw(),0x1a10,address(&first));
        for(auto& row:logical) row={0x11223344,0x55667788,0};
        logical[0][2]=address(shader_tokens.data()); logical[1][2]=logical[0][2]; logical[2][2]=address(shader_tokens.data()+1);
        globals.mode_00=1; globals.observed_mode_01=1; globals.preserved_02[0]=0x65; globals.preserved_02[1]=0x76; globals.nesting_04=0;
    }
    ~Fixture() {
        while(lock.native.RecursionCount>0) LeaveCriticalSection(&lock.native);
        DeleteCriticalSection(&lock.native);
    }
    void* raw() { return renderer.data(); }
    void* owner(unsigned i) { return logical[i].data(); }
    Word cache_id() {
        const Word cached=load(raw(),cache_offset); if(cached==0) return 0;
        for(Word i=0;i<logical.size();++i) if(cached==address(owner(i))) return i+1;
        throw std::runtime_error("unknown logical cache identity");
    }
    Word shader_id(void* shader) { if(!shader) return 0; if(shader==shader_tokens.data()) return 1; require(shader==shader_tokens.data()+1,"shader identity"); return 2; }
    void guards() {
        for(Word i=0;i<renderer.size();++i) {
            if((i>=4&&i<8)||(i>=cache_offset&&i<cache_offset+4)||(i>=counter_offset&&i<counter_offset+4)||(i>=0x1a10&&i<0x1a14)) continue;
            require(renderer[i]==0xa5,"unrelated renderer bytes");
        }
        for(const auto& row:logical) require(row[0]==0x11223344 && row[1]==0x55667788,"borrowed logical header/refcounts");
        require(globals.preserved_02[0]==0x65 && globals.preserved_02[1]==0x76,"synchronization padding");
    }
};
std::int32_t __stdcall set_shader(Device* device,void* shader) {
    auto& f=*device->fixture; ++f.calls;
    require(globals.mode_00==1 && globals.nesting_04==1 && f.lock.depth==1 && f.lock.native.RecursionCount==1,"guard surrounds COM");
    f.events.push_back({device->id,f.shader_id(shader),f.cache_id(),load(f.raw(),f.counter_offset),globals.mode_00,globals.nesting_04,static_cast<Word>(f.lock.depth)});
    if(f.throwing) { store(f.raw(),f.counter_offset,123); throw std::runtime_error("scripted COM exception"); }
    if(f.calls==1) {
        require(device->id==1 && f.cache_id()==1 && f.shader_id(shader)==1,"initial cache publication/device capture");
        store(f.raw(),f.cache_offset,address(f.owner(1))); store(f.raw(),0x1a10,address(&f.second)); store(f.raw(),f.counter_offset,0xffffffffu);
        return static_cast<std::int32_t>(0x80004005u);
    }
    require(device->id==2,"reload current device");
    if(f.calls==2) { require(f.cache_id()==3 && f.shader_id(shader)==2,"second shader publication"); store(f.raw(),f.counter_offset,10); return 0; }
    if(f.calls==3) { require(f.cache_id()==0 && shader==nullptr,"null transition"); store(f.raw(),f.counter_offset,20); return 1; }
    if(f.calls==4) { require(f.cache_id()==4 && shader==nullptr,"nonnull logical with null COM still binds"); store(f.raw(),f.counter_offset,30); return static_cast<std::int32_t>(0x80004005u); }
    require(f.calls==5 && f.cache_id()==0 && shader==nullptr,"null transition from logical null COM");
    store(f.raw(),f.counter_offset,40); globals.mode_00=0; return 0;
}
Snapshot scenario(Entry original,Source source,bool native,bool vertex) {
    Fixture f(vertex); f.table[(vertex?0x170:0x1ac)/4]=reinterpret_cast<Word>(&set_shader);
    auto bind=[&](void* shader) { if(native) original(f.raw(),0,shader); else source(f.raw(),shader,globals); };
    globals.mode_00=0; bind(nullptr); require(f.calls==0 && globals.nesting_04==0,"disabled null-null guard"); globals.mode_00=1;
    bind(nullptr); require(f.calls==0 && f.cache_id()==0 && globals.nesting_04==0 && f.lock.depth==0,"enabled null-null skip");
    bind(f.owner(0)); require(f.calls==1 && f.cache_id()==2 && load(f.raw(),f.counter_offset)==0,"HRESULT ignored/current counter wraps/cache mutation retained");
    bind(f.owner(0)); require(f.calls==1 && f.cache_id()==2,"equivalent COM retains old logical identity");
    bind(f.owner(2)); require(f.calls==2 && load(f.raw(),f.counter_offset)==11,"current counter reload");
    bind(nullptr); require(f.calls==3 && load(f.raw(),f.counter_offset)==21,"positive HRESULT ignored");
    bind(nullptr); require(f.calls==3 && load(f.raw(),f.counter_offset)==21,"second null-null skip");
    bind(f.owner(3)); require(f.calls==4 && f.cache_id()==4 && load(f.raw(),f.counter_offset)==31,"null COM on nonnull logical");
    bind(f.owner(4)); require(f.calls==4 && f.cache_id()==4,"equal null COM retains logical identity");
    bind(nullptr); require(f.calls==5 && load(f.raw(),f.counter_offset)==41,"returning COM final current count");
    require(globals.mode_00==0 && globals.nesting_04==1 && f.lock.depth==1,"current-mode exit skips leave");
    f.guards(); Snapshot result{f.cache_id(),static_cast<Device*>(pointer(load(f.raw(),0x1a10)))->id,load(f.raw(),f.counter_offset),globals.mode_00,globals.observed_mode_01,globals.nesting_04,static_cast<Word>(f.lock.depth),f.events};
    globals.mode_00=1; bsp::leave_native_renderer_optional_guard_00b33b00(f.raw(),0,globals);
    require(globals.nesting_04==0 && f.lock.depth==0,"fixture releases retained real guard"); return result;
}
void source_exception(Source source,bool vertex) {
    Fixture f(vertex); f.throwing=true; f.table[(vertex?0x170:0x1ac)/4]=reinterpret_cast<Word>(&set_shader);
    bool caught=false; try { source(f.raw(),f.owner(0),globals); } catch(const std::runtime_error&) { caught=true; }
    require(caught && f.calls==1 && globals.nesting_04==0 && f.lock.depth==0,"source C++ guard cleanup");
    require(f.cache_id()==1 && load(f.raw(),f.counter_offset)==123,"throw retains cache/provider writes without increment or rollback"); f.guards();
}
void module_record(const wchar_t* name,HMODULE module,const char* category) {
    if(!module) { std::printf("UNLOADED_RUNTIME|%ls\n",name); return; }
    wchar_t reported[1024],canonical[1024]; const DWORD n=GetModuleFileNameW(module,reported,1024); require(n&&n<1024,"module path");
    HANDLE file=CreateFileW(reported,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr); require(file!=INVALID_HANDLE_VALUE,"module file");
    const DWORD m=GetFinalPathNameByHandleW(file,canonical,1024,FILE_NAME_NORMALIZED); CloseHandle(file); require(m&&m<1024,"canonical module file");
    const auto* data=reinterpret_cast<const unsigned char*>(module); const auto* dos=reinterpret_cast<const IMAGE_DOS_HEADER*>(data); const auto* nt=reinterpret_cast<const IMAGE_NT_HEADERS32*>(data+dos->e_lfanew);
    require(nt->FileHeader.Machine==IMAGE_FILE_MACHINE_I386,"loaded x86 machine"); std::printf("%s|%ls|%ls|%ls|%04x\n",category,name,reported,canonical,static_cast<unsigned>(nt->FileHeader.Machine));
}
void provider_record(const wchar_t* role,void* function) {
    HMODULE module{}; require(GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS|GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,reinterpret_cast<LPCWSTR>(function),&module)!=0,"Win32 provider module");
    std::printf("PROVIDER_ADDRESS|%ls|%08x\n",role,address(function)); module_record(role,module,"LOADED_PROVIDER");
}
} // namespace
int main() {
    try {
        Original vertex(original_00b21d10),pixel(original_00b21c20); vertex.finish(0x00cbce38); pixel.finish(0x00cbce18);
        require(scenario(vertex.entry(),&bsp::bind_native_renderer_vertex_shader_00b21d10,true,true)==scenario(vertex.entry(),&bsp::bind_native_renderer_vertex_shader_00b21d10,false,true),"vertex original/source");
        require(scenario(pixel.entry(),&bsp::bind_native_renderer_pixel_shader_00b21c20,true,false)==scenario(pixel.entry(),&bsp::bind_native_renderer_pixel_shader_00b21c20,false,false),"pixel original/source");
        source_exception(&bsp::bind_native_renderer_vertex_shader_00b21d10,true); source_exception(&bsp::bind_native_renderer_pixel_shader_00b21c20,false);
        for(const auto* name:{L"ucrtbase.dll",L"vcruntime140.dll",L"msvcp140.dll",L"vcruntime140_1.dll",L"kernel32.dll",L"ntdll.dll"}) module_record(name,GetModuleHandleW(name),"LOADED_RUNTIME");
        provider_record(L"EnterCriticalSection",reinterpret_cast<void*>(&::EnterCriticalSection)); provider_record(L"LeaveCriticalSection",reinterpret_cast<void*>(&::LeaveCriticalSection));
        std::puts("PASS: two complete original/source shader binders, ten-call transition trace each, real guard/current cache/device/counter behavior, source-only C++ exception cleanup");
        return 0;
    } catch(const std::exception& error) { std::fprintf(stderr,"FAIL: %s\n",error.what()); return 1; }
}

